use crate::aap::caps::notifier;
use crate::aap::caps::types::{Importance, ItemVerdict};

struct Node;

fn importance_label(importance: Importance) -> &'static str {
    match importance {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn render(date: &str, overview: &str, entries: &[ItemVerdict]) -> String {
    let mut out = String::new();
    out.push_str("Digest ");
    out.push_str(date);
    out.push('\n');
    out.push_str(overview);
    out.push('\n');
    for entry in entries.iter().filter(|e| e.kept) {
        out.push_str("\n- [");
        out.push_str(importance_label(entry.importance));
        out.push_str("] ");
        out.push_str(&entry.title);
        out.push_str(" — ");
        out.push_str(&entry.link);
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let Digest {
            date,
            overview,
            entries,
            considered,
        } = composed;

        let message = render(&date, &overview, &entries);
        let published = notifier::notify(&message);

        PublishedDigest {
            date,
            considered,
            published,
        }
    }
}

export!(Node);
